"""BAT-02 batch job runner migration."""

from typing import Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], object]) -> list[dict]:
    """Run scheduled jobs sequentially using legacy ON_ERROR semantics."""
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]
        retries = on_error["retries"] if policy == "RETRY" else 0
        attempts = 0

        while True:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "RETRY" and attempts <= retries:
                    continue

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
